import{z as m,x as p,o as t,c as A,q as r,j as s,D as e,d as i,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"递归效用 Epstein–Zin","description":"","frontmatter":{"title":"递归效用 Epstein–Zin","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/recursive-utility.md","filePath":"econ/recursive-utility.md","lastUpdated":1791413859000}'),B={name:"econ/recursive-utility.md"};function d(u,a,c,h,C,S){const n=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="递归效用-epstein–zin" tabindex="-1">递归效用 Epstein–Zin <a class="header-anchor" href="#递归效用-epstein–zin" aria-label="Permalink to &quot;递归效用 Epstein–Zin&quot;">​</a></h1><div class="epigraph"><p>风险厌恶管的是对给定消费彩票的态度，跨期替代管的是确定路径上的早晚；时间可分期望效用把二者锁成互为倒数，递归效用把锁打开。</p><footer>—— Epstein and Zin, Substitution, Risk Aversion, and the Temporal Behavior of Consumption and Asset Returns, Econometrica, 1989</footer></div><p><a href="/econ/risk-free-rate-puzzle">上一课</a>表明：CRRA 用同一个 \\(\\gamma\\) 配溢价会搞坏 \\(r_f\\)。Weil 已经暗示拆开 EIS。本课缺口是 Epstein–Zin 的递归效用：让 \\(\\gamma\\) 与 EIS 成为两个参数。不重做两谜的校准表，不把递归效用写成解决所有资产定价问题的开关。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时间可分期望效用 \\(E\\sum\\beta^t u(c_t)\\) 对确定性的跨期替换与对无时风险的厌恶共用 \\(u\\) 的曲率。股权溢价要大曲率，无风险利率要另一套曲率——上一课把冲突写成谜。Epstein 与 Zin（1989）用 Kreps–Porteus 时间偏好，把终身效用写成当期消费与「未来效用的确定等价」的 CES 聚合：EIS 由聚合的替代弹性给出，\\(\\gamma\\) 由确定等价的风险态度给出，二者不必互为倒数。</p><p>缺口是把这套偏好接到已经学过的 \\(m\\)，而不是从公理再讲一遍。后课习惯与长期风险会用这个装置；本课只钉分离本身。</p><p><span class="marginnote">直觉类比：把终身效用想成一道「今天吃多少、明天怎么过」的配方。期望效用强制同一味调料（\\(u\\) 的曲率）既决定你多怕今天的消费彩票，又决定你多愿意把消费挪到明天；Epstein–Zin 把配方拆成两个独立旋钮——\\(\\gamma\\) 管怕不怕彩票，EIS 管挪不挪时间。</span></p><p><span class="marginnote">EIS 高：确定的消费增长变动时，愿意大幅调整储蓄。\\(\\gamma\\) 高：同期消费彩票要大补偿。CRRA 强迫 EIS\\(=1/\\gamma\\)；EZ 允许例如高 \\(\\gamma\\)、高 EIS 同时出现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递归</p> \\[V_t=\\Bigl[(1-\\beta)c_t^{1-\\rho}+\\beta\\bigl(\\mathrm{E}_t[V_{t+1}^{1-\\gamma}]\\bigr)^{\\frac{1-\\rho}{1-\\gamma}}\\Bigr]^{\\frac{1}{1-\\rho}}, \\]<p>EIS \\(=1/\\rho\\)，\\(\\gamma\\) 为相对风险厌恶。定价核不再只是消费增长的幂，还含财富（或续值）的创新：对长期消息的态度进入 \\(m\\)。\\(\\gamma=\\rho\\) 时退回时间可分 CRRA。</p>',12)),(t(),s(l,null,{default:e(()=>[o(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRRA%5B%22%E6%97%B6%E9%97%B4%E5%8F%AF%E5%88%86%20CRRA%22%5D%20--%3E%20LOCK%5B%22gamma%20%E4%B8%8E%20EIS%20%E4%BA%92%E4%B8%BA%E5%80%92%E6%95%B0%22%5D%0A%20%20LOCK%20--%3E%20TWIN%5B%22%E4%B8%A4%E8%B0%9C%E7%BB%91%E5%9C%A8%E4%B8%80%E4%B8%AA%E6%97%8B%E9%92%AE%22%5D%0A%20%20EZ%5B%22Epstein-Zin%20%E9%80%92%E5%BD%92%22%5D%20--%3E%20SPLIT%5B%22gamma%20%E4%B8%8E%20EIS%20%E5%88%86%E5%BC%80%22%5D%0A%20%20SPLIT%20--%3E%20M%5B%22m%20%E5%90%AB%E7%BB%AD%E5%80%BC%E5%88%9B%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"分离是必要不是充分。高 \\(\\gamma\\) 加高 EIS 可以让预防性项与增长项重新搭配，减轻 Weil 的 \\(r_f\\) 压力，但总量消费仍然平滑——溢价还可以不够。长期风险课会给续值一个持久的消费增长因子；本课不预支 Bansal–Yaron 的校准。",-1)),a[4]||(a[4]=E("h3",{id:"多了一项",tabindex:"-1"},[i("\\(m\\) 多了一项 "),E("a",{class:"header-anchor",href:"#多了一项","aria-label":'Permalink to "$m$ 多了一项"'},"​")],-1)),a[5]||(a[5]=E("p",null,"EZ 的欧拉对财富回报有暴露。市场组合（或总财富）的创新进入定价，即便当期 \\(\\Delta c\\) 不动。这与下一课习惯（让当期 \\(c\\) 相对习惯更敏感）是不同技术：一个改对新闻的态度，一个改对哪一段消费敏感。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"机制是时间偏好的递归结构。今天的效用取决于今天的 \\(c\\) 和对明天 \\(V\\) 的风险调整。不愿跨期替代的人，可以并不特别厌恶静态彩票，反之亦然。资产若在续值差的时候赔钱，即令当期消费还没动，也会要求溢价——因为 \\(V\\) 已经差了。这为「新闻溢价」准备了语言，本课只把语言接到 SDF，不估计新闻回归。",-1)),(t(),s(l,null,{default:e(()=>[o(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E4%BB%8A%E5%A4%A9%E7%9A%84%E6%B6%88%E8%B4%B9%20c%22%5D%20--%3E%20AGG%5B%22CES%20%E8%81%9A%E5%90%88%EF%BC%9A%E5%BD%93%E6%9C%9F%E4%B8%8E%E6%9C%AA%E6%9D%A5%E6%8B%BC%E6%88%90%E4%BB%8A%E5%A4%A9%E7%9A%84%E6%95%88%E7%94%A8%22%5D%0A%20%20FUT%5B%22%E6%98%8E%E5%A4%A9%E7%9A%84%E7%BB%AD%E5%80%BC%20V(next)%22%5D%20--%3E%20CE%5B%22%E5%85%88%E5%81%9A%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E4%BB%B7%EF%BC%8C%CE%B3%20%E7%AE%A1%E8%BF%99%E4%B8%80%E6%AD%A5%22%5D%0A%20%20CE%20--%3E%20AGG%0A%20%20EIS%5B%22%E8%81%9A%E5%90%88%E7%9A%84%E6%9B%BF%E4%BB%A3%E5%BC%B9%E6%80%A7%20%3D%20EIS%20%3D%201%2F%CF%81%EF%BC%8C%E7%AE%A1%E8%BF%99%E4%B8%80%E6%AD%A5%22%5D%20--%3E%20AGG%0A%20%20AGG%20--%3E%20V%5B%22%E4%BB%8A%E5%A4%A9%E7%9A%84%E7%BB%88%E8%BA%AB%E6%95%88%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">术语翻译：「续值创新」就是关于未来消费机会的意外消息——不是今天的收入变了，而是你听说往后的日子要变好或变坏。资产若恰好在坏消息传来时赔钱，哪怕今天的消费纹丝不动，持有人也已经在最难过的状态下受伤，因此必须给他溢价才肯持有。</span></p><p>两谜：\\(\\gamma\\) 可以专管 \\(\\sigma(m)\\) 里与风险有关的部分，\\(\\rho\\) 专管 \\(r_f\\) 对增长的敏感。能否同时匹配仍是定量问题；Weil 自己稍后也讨论过递归偏好下谜是否还在。本课禁止宣布「EZ 已经关掉两谜」。</p><p><span class="marginnote">Epstein and Zin, <em>Econometrica</em> 1989；实证资产定价常用的另一篇是 1991 年 <em>JPE</em>。不要发明 arXiv。Kreps–Porteus 是时间偏好公理，本课不重证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 EZ 写成 EMH 或写成因子模型。截面仍可能要可交易因子，见量化栏；本栏只改 \\(m\\) 的形状。下一课 <a href="/econ/habit-formation">习惯形成</a>用另一条路让风险厌恶随状态变，不必靠续值新闻。两者是并列修补，不是互相引理。</p><p>后课默认：EIS 与 \\(\\gamma\\) 可以分开；定价核可含财富/续值创新。时间可分 CRRA 是 \\(\\gamma=\\rho\\) 的特例。两谜的定量解决不在本课宣布。</p><p>偏好参数仍受微观证据约束。拆开不是许可证把 \\(\\gamma\\) 放到任意大。</p><p>若 EIS\\(\\lt 1\\)，长期好消息可以压低资产价格（收入效应主导），长期风险课的符号会翻。本课必须先允许 EIS 自由，后课才谈「通常要 EIS\\(\\gt 1\\)」。习惯形成不需要这条符号，它改的是 surplus，不是续值对增长新闻的加载。</p><p><span class="marginnote">数字实例：EIS\\(\\lt1\\) 意味着收入效应压过替代效应。想象你得知未来每年收入将永久多 10%——你反而想立刻多消费、少储蓄，把储蓄从市场抽走会推高折现率、压低资产价格。所以「长期好消息」可能让股价下跌，符号取决于 EIS 在 1 的哪一侧。</span></p><p>截面上用财富回报当第二因子，看起来像 ICAPM。那是后课与量化栏的映射，不是 Epstein–Zin 颁发的可交易组合名单。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Epstein–Zin：递归聚合拆开相对风险厌恶与 EIS。</li><li>定价核除消费增长外，可对续值（财富）创新暴露。</li><li>拆开是对付 Weil 孪生之谜的必要步骤，不是自动的充分解。</li><li>出处：Epstein and Zin, <em>Econometrica</em> 1989。</li></ul>',12))])}const D=m(B,[["render",d]]);export{f as __pageData,D as default};
